+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days, actual use from every `consume` movement, and
+ * the difference (actual − theoretical), for items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const sale of store.data.sales ?? []) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const n of saleUse(store, sale)) theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0 || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return listItems(store)
+    .map((item) => {
+      const t = r3(theoretical.get(item.id) ?? 0);
+      const a = r3(actual.get(item.id) ?? 0);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: r3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
