@@ -0,0 +1,50 @@
+// Till sales: each dish sold uses one portion of its recipe per `qty`.
+// A ticket is imported once; importing is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when sales for `ticket` were already imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient use of one sale line: its recipe scaled to `qty` portions. */
+export function saleUse(store, sale) {
+  const dish = getDish(store, sale.dishId);
+  return scaled(getRecipe(store, dish.recipeId), sale.qty).filter((n) => n.qty > 0);
+}
+
+/**
+ * Records sale lines { row, ticket, soldAt, dishId, qty } and consumes their
+ * ingredients (ref `sale:<ticket>`). Tickets already imported are skipped.
+ * Checks all stock first; throws import_not_enough_stock naming the row.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const need = new Map();
+  for (const l of fresh) {
+    for (const n of saleUse(store, l)) {
+      const total = round3((need.get(n.itemId) ?? 0) + n.qty);
+      const available = round3(onHand(store, n.itemId));
+      if (total > available) {
+        const item = getItem(store, n.itemId);
+        throw new AppError("import_not_enough_stock", { row: l.row, item: item.name, available, unit: item.unit });
+      }
+      need.set(n.itemId, total);
+    }
+  }
+  store.data.sales ??= [];
+  for (const l of fresh) {
+    for (const n of saleUse(store, l)) consume(store, n.itemId, n.qty, { at: l.soldAt, ref: `sale:${l.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: l.ticket, soldAt: l.soldAt, dishId: l.dishId, qty: l.qty });
+  }
+  return {
+    tickets: new Set(fresh.map((l) => l.ticket)).size,
+    dishes: fresh.reduce((s, l) => s + l.qty, 0),
+  };
+}
